//! 🧭️ Cooperative graph laws borrow source rows and yield before every bounded comparison.
use super::*;
use super::super::graph::{LayoutGraphRead,ContentOwner,FrameRead,FrameContentRead};
use super::index::{Slots,Entry,HASH_OFFSET,hash_byte,start};
use std::sync::atomic::Ordering;
use std::future::Future;
use std::pin::Pin;
use std::task::{Context,Poll};

struct Tick(bool);
impl Future for Tick {type Output=();fn poll(mut self:Pin<&mut Self>,_:&mut Context<'_>)->Poll<()>{if self.0{Poll::Ready(())}else{self.0=true;Poll::Pending}}}
async fn tick(){Tick(false).await}
async fn same(a:&str,b:&str)->bool{if a.len()!=b.len(){tick().await;return false}let mut at=0;while at<a.len(){tick().await;let end=a.len().min(at.saturating_add(256));if a.as_bytes()[at..end]!=b.as_bytes()[at..end]{return false}at=end;}true}
async fn nonempty(text:&str)->bool{let mut at=0;while at<text.len(){tick().await;let mut used=0;for ch in text[at..].chars().take(64){used+=ch.len_utf8();if !ch.is_whitespace(){return true}if used>=256{break}}at+=used;}false}
async fn lookup<'a>(d:&dyn LayoutGraphRead,index:Slots<'a>,kind:u8,owner:usize,target:&str)->Option<(usize,&'a Entry)>{if index.len()==0{tick().await;return None}let mut hash=HASH_OFFSET;let mut at=0;while at<target.len(){tick().await;let end=target.len().min(at.saturating_add(256));for byte in &target.as_bytes()[at..end]{hash=hash_byte(hash,*byte)}at=end;}let mut probe=start((kind,owner),hash,index.len());for _ in 0..index.len(){tick().await;let Some((held,entry))=index.get(probe)else{return None};if *held==(kind,owner,hash)&&same(entry.address.text(d),target).await{return Some((probe,entry))}probe=(probe+1)&(index.len()-1);}None}
async fn contains(d:&dyn LayoutGraphRead,index:Slots<'_>,kind:u8,owner:usize,target:&str)->bool{lookup(d,index,kind,owner,target).await.is_some()}
fn require(valid:bool,message:&'static str)->Result<(),&'static str>{if valid{Ok(())}else{Err(message)}}
fn drawing_member(d:&dyn LayoutGraphRead,at:usize)->Option<&crate::LayoutDrawingMember>{d.drawing(if at==0{crate::DrawingSourceAddress::Document}else{crate::DrawingSourceAddress::Page(at-1)})}
async fn drawing_members(d:&dyn LayoutGraphRead)->Validation{for at in 0..=d.page_count(){tick().await;let Some(member)=drawing_member(d,at)else{continue};let h=&member.handle;let dialect=&h.target.dialect;require(nonempty(&h.child_id).await&&nonempty(&h.target.artifact_id).await&&same(&dialect.artifact_kind,"s.draw.drawing").await&&same(&dialect.standard,"1").await&&same(&dialect.subset,"*").await,"Drawing member references must have independent identities and the genuine Draw dialect.")?;for earlier in 0..at{tick().await;if let Some(old)=drawing_member(d,earlier){require(!same(&old.handle.child_id,&h.child_id).await&&!same(&old.handle.target.artifact_id,&h.target.artifact_id).await,"Page Drawing children must have independent local and target identities.")?}}}Ok(())}
async fn runs(d:&dyn LayoutGraphRead,index:Slots<'_>,owner:usize)->Validation{let story=d.story(owner);for row in 0..d.run_count(owner){tick().await;let run=d.run(owner,row);require(run.start<=run.end&&usize::try_from(run.start).is_ok_and(|n|story.content.is_char_boundary(n))&&usize::try_from(run.end).is_ok_and(|n|story.content.is_char_boundary(n)),"Style runs must stay inside the story on UTF-8 character boundaries.")?;if let Some(id)=run.paragraph_style_id.as_deref(){require(contains(d,index,0,0,id).await,"Style runs must name existing styles.")?}if let Some(id)=run.character_style_id.as_deref(){require(contains(d,index,1,0,id).await,"Style runs must name existing styles.")?}}Ok(())}
async fn content(d:&dyn LayoutGraphRead,index:Slots<'_>,owner:usize,parent:bool)->Validation{
 let at=if parent{ContentOwner::Parent(owner)}else{ContentOwner::Page(owner)};let kind=if parent{7}else{9};require(d.cached_layer_count(at)==d.layer_count(at),"Layer membership must match the owning layer order.")?;for row in 0..d.layer_count(at){tick().await;require(same(d.cached_layer(at,row),d.layer_id(at,row)).await,"Layer membership must match the owning layer order.")?}
 for row in 0..d.frame_count(at){tick().await;let frame=d.frame(at,row);let(_,layer)=lookup(d,index,kind,owner,frame.layer_id).await.ok_or("Every frame must belong to an existing owning layer.")?;let member=layer.increment_count();require(member<d.member_count(at,layer.address.row)&&same(d.member(at,layer.address.row,member),frame.id).await,"Layer object membership must match its frames in paint order.")?;super::super::validate_frame_bounds(frame.bounds)?;match frame.content{FrameContentRead::Rect{fill,stroke}=>require(super::super::color_valid(&fill)&&super::super::color_valid(&stroke),"Frame colors must be finite.")?,FrameContentRead::Text{story_id,columns,inset,..}=>{require(contains(d,index,2,0,story_id).await,"Text frames must name an existing story.")?;require(columns>0&&super::super::rect_valid(inset),"Text columns must be positive and inset sizes finite and non-negative.")?},FrameContentRead::Image{link_id}=>require(contains(d,index,3,0,link_id).await,"Image frames must name an existing link.")?}}
 for row in 0..d.layer_count(at){tick().await;let(_,held)=lookup(d,index,kind,owner,d.layer_id(at,row)).await.expect("admitted original layer index");require(held.count()==d.member_count(at,row),"Layer object membership must match its frames in paint order.")?}Ok(())
}
#[derive(Clone)]struct Frames{parent:Option<usize>,page:usize,frame:usize}
impl Frames{fn local()->Self{Self{parent:None,page:0,frame:0}}fn parent(index:usize)->Self{Self{parent:Some(index),page:0,frame:0}}async fn next<'a>(&mut self,d:&'a dyn LayoutGraphRead)->Option<FrameRead<'a>>{loop{tick().await;let owner=match self.parent{Some(index)=>{if self.page>0{return None}ContentOwner::Parent(index)},None=>{if self.page==d.page_count(){return None}ContentOwner::Page(self.page)}};if self.frame<d.frame_count(owner){let row=self.frame;self.frame+=1;return Some(d.frame(owner,row))}self.page+=1;self.frame=0;}}}
async fn threads(d:&dyn LayoutGraphRead,index:Slots<'_>,source:Frames)->Validation{
 let kind=if source.parent.is_some(){8}else{10};let owner=source.parent.unwrap_or(0);let mut frames=source.clone();while let Some(frame)=frames.next(d).await{if let FrameContentRead::Text{story_id,thread_next:Some(next),..}=frame.content{let(_,entry)=lookup(d,index,kind,owner,frame.id).await.expect("admitted frame source index");let(to,target)=lookup(d,index,kind,owner,next).await.ok_or("Thread targets must be existing text frames in the same content graph.")?;let target_frame=d.frame(match source.parent{Some(parent)=>ContentOwner::Parent(parent),None=>ContentOwner::Page(target.address.owner)},target.address.row);let FrameContentRead::Text{story_id:target_story,..}=target_frame.content else{return Err("Thread targets must be existing text frames in the same content graph.")};require(same(story_id,target_story).await,"Thread edges must connect frames of the same story.")?;require(target.incoming.fetch_add(1,Ordering::Relaxed)==0,"Text frames must have at most one predecessor.")?;entry.next.store(to,Ordering::Relaxed);}}
 let mut roots=source.clone();while let Some(frame)=roots.next(d).await{let(root,_)=lookup(d,index,kind,owner,frame.id).await.expect("admitted thread root index");let mut at=root;while at!=usize::MAX{tick().await;let(_,entry)=index.get(at).expect("existing next frame slot");match entry.mark.load(Ordering::Relaxed){2=>break,1=>return Err("Text threads must not contain cycles."),_=>{entry.mark.store(1,Ordering::Relaxed);at=entry.next.load(Ordering::Relaxed)}}}let mut at=root;while at!=usize::MAX{tick().await;let(_,entry)=index.get(at).expect("existing thread finalization slot");if entry.mark.load(Ordering::Relaxed)==2{break}entry.mark.store(2,Ordering::Relaxed);at=entry.next.load(Ordering::Relaxed);}}Ok(())
}
pub(super) async fn check_document(d:&dyn LayoutGraphRead,index:Slots<'_>)->Validation{
 tick().await;let grid=d.grid();require(same(d.schema(),crate::LAYOUT_DOCUMENT_SCHEMA).await,"The document schema is unsupported.")?;require(super::super::positive(grid.baseline_grid)&&grid.baseline_offset.is_finite(),"The baseline grid must be positive and finite and its offset finite.")?;
 for row in 0..d.paragraph_count(){tick().await;let style=d.paragraph(row);require(nonempty(style.name).await&&nonempty(style.font_family).await&&super::super::positive(style.font_size)&&super::super::positive(style.leading)&&style.tracking.is_finite()&&style.font_weight>0&&matches!(style.alignment,"left"|"center"|"right"|"justify"),"Paragraph typography must have valid names, sizes, weight, tracking, and alignment.")?}
 for row in 0..d.character_count(){tick().await;let style=d.character(row);require(style.font_size.is_none_or(super::super::positive)&&style.font_weight.is_none_or(|w|w>0)&&style.tracking.is_none_or(f64::is_finite)&&super::super::color_valid(&style.color),"Character typography must have positive sizes and weight and finite tracking and colors.")?}
 for row in 0..d.story_count(){tick().await;runs(d,index,row).await?}
 for row in 0..d.parent_count(){tick().await;let parent=d.parent(row);require(nonempty(parent.name).await&&super::super::positive(parent.width)&&super::super::positive(parent.height),"Parent pages need a name and positive finite dimensions.")?;content(d,index,row,true).await?;threads(d,index,Frames::parent(row)).await?}
 for row in 0..d.spread_count(){tick().await;let spread=d.spread(row);require(nonempty(spread.name).await,"Spreads need a name.")?;for member in 0..d.spread_page_count(row){tick().await;let valid=match lookup(d,index,6,0,d.spread_page(row,member)).await{Some((_,entry))=>same(d.page(entry.address.row).spread_id,spread.id).await,None=>false};require(valid,"Spread members must exist and belong to that spread.")?}}
 for row in 0..d.page_count(){tick().await;let page=d.page(row);let valid=match lookup(d,index,5,0,page.spread_id).await{Some((_,entry))=>contains(d,index,12,entry.address.row,page.id).await,None=>false};require(valid,"Every page must be a member of its existing spread.")?;
 require(super::super::positive(page.width)&&super::super::positive(page.height),"Pages need positive finite dimensions.")?;require(page.margins.iter().all(|n|n.is_finite())&&page.columns>0&&super::super::nonnegative(page.gutter),"Page margins must be finite, columns positive, and gutter and guide sizes finite and non-negative.")?;for guide in 0..d.guide_count(row){tick().await;require(super::super::rect_valid(d.guide(row,guide)),"Page margins must be finite, columns positive, and gutter and guide sizes finite and non-negative.")?}
 content(d,index,row,false).await?;let mut parent=None;if let Some(id)=page.parent_page_id{parent=lookup(d,index,4,0,id).await.map(|(_,entry)|entry.address.row);require(parent.is_some(),"Page parents must exist.")?}
 for member in 0..d.override_count(row){tick().await;let entry=d.page_override(row,member);let exists=match parent{Some(parent)=>contains(d,index,8,parent,entry.object_id).await,None=>false};require(exists&&entry.bounds.is_none_or(|b|super::super::bounds_valid(b,true)),"Overrides must name inherited frames and have finite non-negative bounds.")?}
 if let Some(parent)=parent{for member in 0..d.frame_count(ContentOwner::Page(row)){tick().await;require(!contains(d,index,8,parent,d.frame(ContentOwner::Page(row),member).id).await,"Inherited and local frame ids must not collide on a page.")?}}
 }
 threads(d,index,Frames::local()).await?;drawing_members(d).await?;Ok(())
}
